(4817641, 695602, 42013, '<td valign="top">You might be interested in this website-- <a href="//singhray.blogspot.com" rel="nofollow" target="_blank">Here-See Palouse posting</a></td>', 'You might be interested in this website-- Here-See Palouse posting', '2008-07-10 17:13:56.000000', NULL, 1),
(4817642, 696871, 42013, '<td valign="top">Without a doubt the best fireworks picture I have seen in recent memory. I tried this 4th of July and failed miserably so I''ll be interested to see the specifics. Good job!</td>', 'Without a doubt the best fireworks picture I have seen in recent memory. I tried this 4th of July and failed miserably so I''ll be interested to see the specifics. Good job!', '2008-07-10 17:14:34.000000', NULL, 1),
(4817643, 696526, 62895, '<td valign="top">You have a great photo, with plenty of interest, but it lacks pop. I think by increasing the contrast and possibly adding a little saturation in an editing program you could make this even better.</td>', 'You have a great photo, with plenty of interest, but it lacks pop. I think by increasing the contrast and possibly adding a little saturation in an editing program you could make this even better.', '2008-07-10 17:15:58.000000', NULL, 1),
(4817644, 696914, 62895, '<td valign="top">Brilliant and original. You took something that''s hard to photograph, and made it look magical.</td>', 'Brilliant and original. You took something that''s hard to photograph, and made it look magical.', '2008-07-10 17:18:12.000000', NULL, 1),
(4817645, 697097, 62895, '<td valign="top">A surreal effect. The colors don''t look natural, but it works. 7</td>', 'A surreal effect. The colors don''t look natural, but it works. 7', '2008-07-10 17:19:21.000000', NULL, 1),
