(4817652, 694457, 62895, '<td valign="top">I like the long exposure, and the majestic bridge. The colors seem quite warm though.</td>', 'I like the long exposure, and the majestic bridge. The colors seem quite warm though.', '2008-07-10 17:23:10.000000', NULL, 1),
(4817655, 695602, 62895, '<td valign="top">Good eye, and processing. I never would have thought something that simple could be so beautiful.</td>', 'Good eye, and processing. I never would have thought something that simple could be so beautiful.', '2008-07-10 17:25:22.000000', NULL, 1),
(4817658, 695086, 62895, '<td valign="top">Very chaotic, and the birds add a lot of interest.</td>', 'Very chaotic, and the birds add a lot of interest.', '2008-07-10 17:26:46.000000', NULL, 1),
