(4817707, 696820, 56275, '<td valign="top">Pretty sunset. I think it may be a little over sharpened around the bridge area though?</td>', 'Pretty sunset. I think it may be a little over sharpened around the bridge area though?', '2008-07-10 17:54:26.000000', NULL, 1),
(4817710, 694821, 56275, '<td valign="top">Wow! Quite the storm! Nice shot. I like where you chose to put the horizon.</td>', 'Wow! Quite the storm! Nice shot. I like where you chose to put the horizon.', '2008-07-10 17:55:59.000000', NULL, 1),
(4817715, 696943, 56275, '<td valign="top">Looks like something out of an old photo album. I love the feeling this photo leaves me with. Serene.</td>', 'Looks like something out of an old photo album. I love the feeling this photo leaves me with. Serene.', '2008-07-10 17:56:45.000000', NULL, 1),
(4817717, 696581, 56275, '<td valign="top">Pretty sunset, but I feel the shot could have been improved by adjusting your horizon lower in the frame. Or lightening the foreground. The road and power lines draw your eyes to that part of the photo.</td>', 'Pretty sunset, but I feel the shot could have been improved by adjusting your horizon lower in the frame. Or lightening the foreground. The road and power lines draw your eyes to that part of the photo.', '2008-07-10 17:58:23.000000', NULL, 1),
(4817720, 696577, 56275, '<td valign="top">Very nicely captured! The sky looks beautiful, and the the clarity of the buildings and water is great. Only critique would be the over-saturated (somewhat blown out?) green  in the building on the left. Very nice overall. 8</td>', 'Very nicely captured! The sky looks beautiful, and the the clarity of the buildings and water is great. Only critique would be the over-saturated (somewhat blown out?) green  in the building on the left. Very nice overall. 8', '2008-07-10 17:59:59.000000', NULL, 1),
