(4819781, 696194, 42013, '<td valign="top">Pretty skies and I like the row of trees in the BG.</td>', 'Pretty skies and I like the row of trees in the BG.', '2008-07-11 19:03:55.000000', NULL, 1),
(4819783, 696632, 42013, '<td valign="top">This makes me feel as if I''m floating on the water along with the swans. Nice work!</td>', 'This makes me feel as if I''m floating on the water along with the swans. Nice work!', '2008-07-11 19:04:20.000000', NULL, 1),
(4819784, 697108, 42013, '<td valign="top">Great tones in the dirt, set off nicely by the blue sky. I''m feeling the border is a little heavy but no points off for that.</td>', 'Great tones in the dirt, set off nicely by the blue sky. I''m feeling the border is a little heavy but no points off for that.', '2008-07-11 19:04:57.000000', NULL, 1),
(4819785, 695172, 42013, '<td valign="top">Adding the boy was a great touch. I find the BG a little distracting and wish their was a way to change the camera position slightly to exclude the grey/green bushes in the BG. 7</td>', 'Adding the boy was a great touch. I find the BG a little distracting and wish their was a way to change the camera position slightly to exclude the grey/green bushes in the BG. 7', '2008-07-11 19:05:45.000000', NULL, 1),
(4819786, 695370, 42013, '<td valign="top">Great job on the exposure...not sure if all of the sky as composed works that well. It is a lot of blank area and detracts from the city lights IMHO. 7</td>', 'Great job on the exposure...not sure if all of the sky as composed works that well. It is a lot of blank area and detracts from the city lights IMHO. 7', '2008-07-11 19:06:55.000000', NULL, 1),
(4819787, 696450, 42013, '<td valign="top">Classic scene--the road, the clouds, and the spots of light. 7</td>', 'Classic scene--the road, the clouds, and the spots of light. 7', '2008-07-11 19:07:18.000000', NULL, 1),
