(4820122, 696194, 33672, '<td valign="top">Very very cool photo. Great sky and field. I like the contrasting colors.</td>', 'Very very cool photo. Great sky and field. I like the contrasting colors.', '2008-07-11 23:39:38.000000', NULL, 1),
(4820123, 697014, 33672, '<td valign="top">Is this Niagra Falls? Interesting view of it. Its one of my favorite places on the planet.</td>', 'Is this Niagra Falls? Interesting view of it. Its one of my favorite places on the planet.', '2008-07-11 23:41:21.000000', NULL, 1),
(4820162, 696050, 13207, '<td valign="top">I really like the tones in this shot - only distraction for me is the ground in the lower right hand corner</td>', 'I really like the tones in this shot - only distraction for me is the ground in the lower right hand corner', '2008-07-12 00:27:17.000000', NULL, 1),
(4820173, 696917, 13207, '<td valign="top">Great reflection capture, find the trees to be a little too overwhelming of the shot for me though.</td>', 'Great reflection capture, find the trees to be a little too overwhelming of the shot for me though.', '2008-07-12 00:36:05.000000', NULL, 1),
(4820174, 696988, 13207, '<td valign="top">Definitely a neat view, but somehow I just don''t find this image holds my attention for long - I think it may be a lack of symmetry that you so often seein images like this, I don''t know.  Just my opinion though, good luck!</td>', 'Definitely a neat view, but somehow I just don''t find this image holds my attention for long - I think it may be a lack of symmetry that you so often seein images like this, I don''t know.  Just my opinion though, good luck!', '2008-07-12 00:37:37.000000', NULL, 1),
(4820175, 696178, 13207, '<td valign="top">This image seems a little flat too me.  Perhaps boosting the contrast and adjusting the levels would give this shot a little more oomph.</td>', 'This image seems a little flat too me.  Perhaps boosting the contrast and adjusting the levels would give this shot a little more oomph.', '2008-07-12 00:40:32.000000', NULL, 1),
(4820177, 695832, 13207, '<td valign="top">I like the reflection of the cliffs that you caught in the water however there is an overall lack of focus that, imo, does not enhance this shot.</td>', 'I like the reflection of the cliffs that you caught in the water however there is an overall lack of focus that, imo, does not enhance this shot.', '2008-07-12 00:41:41.000000', NULL, 1),
