(4824212, 696277, 44611, '<td valign="top">Beautiful place, lovely shot.  Shame about the haze - on a clear day this would be fantastic.</td>', 'Beautiful place, lovely shot.  Shame about the haze - on a clear day this would be fantastic.', '2008-07-14 13:44:48.000000', NULL, 1),
(4824218, 695635, 44611, '<td valign="top">Better overall focus particularly in the foreground would have increased the appeal of this picture.  The composition is good with the boulder, but it still comes across a little boring.</td>', 'Better overall focus particularly in the foreground would have increased the appeal of this picture.  The composition is good with the boulder, but it still comes across a little boring.', '2008-07-14 13:46:40.000000', NULL, 1),
(4824219, 695313, 52549, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-07-14 13:46:54.000000', NULL, 1),
(4824222, 696440, 52549, '<td valign="top">Think you had everything working for you that day. Great shot.</td>', 'Think you had everything working for you that day. Great shot.', '2008-07-14 13:47:34.000000', NULL, 1),
(4824223, 696797, 44611, '<td valign="top">Great silhouette, but shoe-horning a bit on landscape.</td>', 'Great silhouette, but shoe-horning a bit on landscape.', '2008-07-14 13:47:43.000000', NULL, 1),
(4824229, 695397, 52549, '<td valign="top">I love the golden tones.</td>', 'I love the golden tones.', '2008-07-14 13:48:55.000000', NULL, 1),
(4824238, 696472, 44611, '<td valign="top">Just a little too dark but might have worked without the shrubs either side.</td>', 'Just a little too dark but might have worked without the shrubs either side.', '2008-07-14 13:50:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4824249, 695578, 44611, '<td valign="top">This is lovely but needs a bit more ''pop'' to the colour imho.</td>', 'This is lovely but needs a bit more ''pop'' to the colour imho.', '2008-07-14 13:52:29.000000', NULL, 1),
(4824257, 696428, 44611, '<td valign="top">Lovely sky and nice silhouettes, but doesn''t show me a lot of landscape.</td>', 'Lovely sky and nice silhouettes, but doesn''t show me a lot of landscape.', '2008-07-14 13:53:50.000000', NULL, 1),
(4824261, 696218, 44611, '<td valign="top">Great title which made a lot of people look closely, I bet!  Could be classed an interesting landscape by a stretch, but pushing it!</td>', 'Great title which made a lot of people look closely, I bet!  Could be classed an interesting landscape by a stretch, but pushing it!', '2008-07-14 13:55:13.000000', NULL, 1),
(4824266, 696572, 44611, '<td valign="top">Lovely seascape.</td>', 'Lovely seascape.', '2008-07-14 13:56:50.000000', NULL, 1),
(4824285, 697090, 44611, '<td valign="top">Beautiful scene and well captured.  A very special place.</td>', 'Beautiful scene and well captured.  A very special place.', '2008-07-14 14:03:59.000000', NULL, 1),
(4824291, 695602, 44611, '<td valign="top">I like this a lot, but have a bit of an issue with the sky/cloud colours - somehow don''t seem quite natural.  Still one of my favs in this challenge.</td>', 'I like this a lot, but have a bit of an issue with the sky/cloud colours - somehow don''t seem quite natural.  Still one of my favs in this challenge.', '2008-07-14 14:05:09.000000', NULL, 1),
(4824292, 696091, 44611, '<td valign="top">Great rural landscape.</td>', 'Great rural landscape.', '2008-07-14 14:05:32.000000', NULL, 1),
(4824295, 696411, 90658, '<td valign="top">Interesting idea.  Please tell me you weren''t driving.</td>', 'Interesting idea.  Please tell me you weren''t driving.', '2008-07-14 14:06:17.000000', NULL, 1),
(4824296, 697097, 44611, '<td valign="top">This is lovely - I really like the foreground grass and the dreamy haze over the trees.  The downside of the haze, of course, is loss of detail in the sky.  If this had a bit more colour then it would have been a 10 for sure.</td>', 'This is lovely - I really like the foreground grass and the dreamy haze over the trees.  The downside of the haze, of course, is loss of detail in the sky.  If this had a bit more colour then it would have been a 10 for sure.', '2008-07-14 14:06:36.000000', NULL, 1),
(4824297, 696615, 44611, '<td valign="top">I love the soft focus on this.  Wish the foreground was a tad sharper.  Intrigued as to which mountain that is?</td>', 'I love the soft focus on this.  Wish the foreground was a tad sharper.  Intrigued as to which mountain that is?', '2008-07-14 14:06:39.000000', NULL, 1),
(4824298, 696503, 44611, '<td valign="top">Fantastic seascape, love the dreamy feel.</td>', 'Fantastic seascape, love the dreamy feel.', '2008-07-14 14:06:43.000000', NULL, 1),
(4824299, 696988, 44611, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2008-07-14 14:06:47.000000', NULL, 1),
(4824301, 695468, 90658, '<td valign="top">Gorgeous!  What is the orange on the right?  I''m thinking it is a light reflection.</td>', 'Gorgeous!  What is the orange on the right?  I''m thinking it is a light reflection.', '2008-07-14 14:07:00.000000', NULL, 1),
(4824304, 695577, 44611, '<td valign="top">Wish there were a bit more detail in the shadows, but still a nice shot.</td>', 'Wish there were a bit more detail in the shadows, but still a nice shot.', '2008-07-14 14:07:27.000000', NULL, 1),
(4824305, 696863, 90658, '<td valign="top">This is wonderful.  I love the juxtaposition of the snow against the "desert.:</td>', 'This is wonderful.  I love the juxtaposition of the snow against the "desert.:', '2008-07-14 14:07:34.000000', NULL, 1),
(4824308, 696984, 90658, '<td valign="top">This is very pretty and and an extraordinary effort for a Basic Editing Challenge.</td>', 'This is very pretty and and an extraordinary effort for a Basic Editing Challenge.', '2008-07-14 14:08:17.000000', NULL, 1),
(4824309, 696390, 44611, '<td valign="top">The sky makes this. A shame about the deep shadows, if there were more detail there it would be fabulous.</td>', 'The sky makes this. A shame about the deep shadows, if there were more detail there it would be fabulous.', '2008-07-14 14:08:23.000000', NULL, 1),
(4824310, 696974, 90658, '<td valign="top">I wish there were more differentiation between the surface and the reflections.  This is pleasant to look at though.</td>', 'I wish there were more differentiation between the surface and the reflections.  This is pleasant to look at though.', '2008-07-14 14:08:58.000000', NULL, 1),
(4824311, 697018, 44611, '<td valign="top">Beautiful - a tad dark, but still very lovely.</td>', 'Beautiful - a tad dark, but still very lovely.', '2008-07-14 14:09:08.000000', NULL, 1),
(4824312, 697013, 90658, '<td valign="top">Could be my eyes, but I am having a hard time finding a focal point.</td>', 'Could be my eyes, but I am having a hard time finding a focal point.', '2008-07-14 14:09:32.000000', NULL, 1),
(4824313, 696456, 44611, '<td valign="top">Great sky, small landscape.</td>', 'Great sky, small landscape.', '2008-07-14 14:09:40.000000', NULL, 1),
(4824315, 696988, 90658, '<td valign="top">Nice capture of a very interesting urban sculpture.</td>', 'Nice capture of a very interesting urban sculpture.', '2008-07-14 14:10:05.000000', NULL, 1),
(4824321, 697097, 90658, '<td valign="top">The mist adds a very ethereal aspect to this.</td>', 'The mist adds a very ethereal aspect to this.', '2008-07-14 14:11:07.000000', NULL, 1),
(4824322, 695016, 90658, '<td valign="top">Nice choice in showing this in something other than color.</td>', 'Nice choice in showing this in something other than color.', '2008-07-14 14:11:33.000000', NULL, 1),
(4824324, 695939, 90658, '<td valign="top">I''m not sure why but my eyes are drawn to the rock separating the waterfalls.  If that was your intent, then you ROCK!!!</td>', 'I''m not sure why but my eyes are drawn to the rock separating the waterfalls.  If that was your intent, then you ROCK!!!', '2008-07-14 14:12:39.000000', NULL, 1),
(4824332, 697083, 90658, '<td valign="top">Stunning use of the natural environment.</td>', 'Stunning use of the natural environment.', '2008-07-14 14:15:56.000000', NULL, 1),
(4824334, 697018, 81082, '<td valign="top">Absolutely perfect.</td>', 'Absolutely perfect.', '2008-07-14 14:16:32.000000', NULL, 1),
(4824337, 695313, 81082, '<td valign="top">Unique.</td>', 'Unique.', '2008-07-14 14:17:22.000000', NULL, 1),
(4824339, 695083, 81082, '<td valign="top">Great angle.</td>', 'Great angle.', '2008-07-14 14:17:43.000000', NULL, 1),
(4824344, 694701, 81082, '<td valign="top">Nice pose &amp; play on words.</td>', 'Nice pose & play on words.', '2008-07-14 14:19:06.000000', NULL, 1),
(4824345, 695118, 81082, '<td valign="top">Too high of a contrast (w/ the grass and what is beyond).</td>', 'Too high of a contrast (w/ the grass and what is beyond).', '2008-07-14 14:20:34.000000', NULL, 1),
(4824348, 696440, 81082, '<td valign="top">Feels very much like a cartoon - like it a lot.</td>', 'Feels very much like a cartoon - like it a lot.', '2008-07-14 14:20:48.000000', NULL, 1),
(4824350, 694551, 81082, '<td valign="top">Typical.</td>', 'Typical.', '2008-07-14 14:21:17.000000', NULL, 1),
(4824353, 695939, 81082, '<td valign="top">Too much of a close-up view.</td>', 'Too much of a close-up view.', '2008-07-14 14:21:45.000000', NULL, 1),
(4824354, 696863, 83313, '<td valign="top">Seems a touch overproccessed, but the title suggests that''s the look you were after.</td>', 'Seems a touch overproccessed, but the title suggests that''s the look you were after.', '2008-07-14 14:21:56.000000', NULL, 1),
(4824358, 696050, 81082, '<td valign="top">Would have been better if it were crisper.</td>', 'Would have been better if it were crisper.', '2008-07-14 14:23:05.000000', NULL, 1),
(4824360, 696832, 81082, '<td valign="top">Like the vantage point a lot.</td>', 'Like the vantage point a lot.', '2008-07-14 14:23:24.000000', NULL, 1),
(4824364, 696575, 83313, '<td valign="top">I wouldn''t quite call this a landscape, but it''s different and I like it, especially the blue sky reflecting off the windows.</td>', 'I wouldn''t quite call this a landscape, but it''s different and I like it, especially the blue sky reflecting off the windows.', '2008-07-14 14:24:31.000000', NULL, 1),
(4824365, 695177, 81082, '<td valign="top">Like the contrast of old and new.</td>', 'Like the contrast of old and new.', '2008-07-14 14:24:35.000000', NULL, 1),
(4824369, 696433, 83313, '<td valign="top">Probably too much detail for 640 pixels. I''d love to see the large version.</td>', 'Probably too much detail for 640 pixels. I''d love to see the large version.', '2008-07-14 14:25:33.000000', NULL, 1),
(4824388, 696988, 83313, '<td valign="top">Although this could fit into the recent "urban landscapes" challenge, I think a straight up view is stretching the basic landscapes definition. Still an interesting viewpoint. Are those sculptures?</td>', 'Although this could fit into the recent "urban landscapes" challenge, I think a straight up view is stretching the basic landscapes definition. Still an interesting viewpoint. Are those sculptures?', '2008-07-14 14:28:59.000000', NULL, 1),
(4824391, 695254, 83313, '<td valign="top">Interesting street photography, though I find it a stretch to call this a landscape.</td>', 'Interesting street photography, though I find it a stretch to call this a landscape.', '2008-07-14 14:30:46.000000', NULL, 1),
(4824392, 696564, 83313, '<td valign="top">Nice view, though I find the greens/yellows to be a little to strong and unrealistic.</td>', 'Nice view, though I find the greens/yellows to be a little to strong and unrealistic.', '2008-07-14 14:31:27.000000', NULL, 1),
(4824395, 695016, 83313, '<td valign="top">I like the old timey look to this. A little colored banding visible in the sky, though.</td>', 'I like the old timey look to this. A little colored banding visible in the sky, though.', '2008-07-14 14:32:47.000000', NULL, 1),
(4824399, 696572, 83313, '<td valign="top">Those birds lined up quite nicely for you.</td>', 'Those birds lined up quite nicely for you.', '2008-07-14 14:33:49.000000', NULL, 1),
(4824404, 695397, 83313, '<td valign="top">Nice, very nice, though I don''t care for the top and bottom frames.</td>', 'Nice, very nice, though I don''t care for the top and bottom frames.', '2008-07-14 14:35:45.000000', NULL, 1),
(4824725, 696557, 75034, '<td valign="top">Ernie, this is a wonderful shot and I''m thrilled that we are on the same team. It was fantastic to meet you and I look forward to going out shooting and taking shots like this:)<br/> <br/>No vote from me for obvious reasons.<br/> <br/>All the best to you mate:)<br/> <br/>MAX!</td>', 'Ernie, this is a wonderful shot and I''m thrilled that we are on the same team. It was fantastic to meet you and I look forward to going out shooting and taking shots like this:) No vote from me for obvious reasons. All the best to you mate:) MAX!', '2008-07-14 17:10:31.000000', NULL, 1),
(4824739, 695830, 75034, '<td valign="top">Michelle, You ROCK and so does this shot. Go team.<br/> <br/>No vote from me for obvious reasons.<br/> <br/>MAX!</td>', 'Michelle, You ROCK and so does this shot. Go team. No vote from me for obvious reasons. MAX!', '2008-07-14 17:13:57.000000', NULL, 1),
(4824869, 696919, 90658, '<td valign="top">I have to say, I''ve not ever seen this angle of Multnomah Falls before.  Usually people go in tighter and leave out the ruggedness of the canyon.  This perspective draws my eye to the final fall below the bridge, something I have not looked at as separate from the rest before.  I drive by here at least 6 times a year and I have now seen something that I hadn''t before.  Thank you for this.</td>', 'I have to say, I''ve not ever seen this angle of Multnomah Falls before.  Usually people go in tighter and leave out the ruggedness of the canyon.  This perspective draws my eye to the final fall below the bridge, something I have not looked at as separate from the rest before.  I drive by here at least 6 times a year and I have now seen something that I hadn''t before.  Thank you for this.', '2008-07-14 18:32:06.000000', NULL, 1),
(4824872, 695769, 90658, '<td valign="top">Very "Achoo-ish."  Compliments.</td>', 'Very "Achoo-ish."  Compliments.', '2008-07-14 18:33:14.000000', NULL, 1),
(4824875, 696647, 90658, '<td valign="top">Mmmmmm...very peaceful.  Scenes like this must make it all worthwhile for the farmer.</td>', 'Mmmmmm...very peaceful.  Scenes like this must make it all worthwhile for the farmer.', '2008-07-14 18:34:20.000000', NULL, 1),
(4824876, 696904, 96371, '<td valign="top">Absolutely breath taking, beautiful compesition leading the viewer into the image and out into the deep blue sky - a favourite</td>', 'Absolutely breath taking, beautiful compesition leading the viewer into the image and out into the deep blue sky - a favourite', '2008-07-14 18:35:03.000000', NULL, 1),
(4824878, 696194, 96371, '<td valign="top">great photo but needs something in the foreground to it better perspective</td>', 'great photo but needs something in the foreground to it better perspective', '2008-07-14 18:37:05.000000', NULL, 1),
(4824882, 696801, 90658, '<td valign="top">Montana is such a wide open space.  I''ve been to the mountains and the plains of Big Sky country.  This is an intriguing shot because it goes against the preconceived ideas that the title infers.  I would expect to see a sweeping shot with plains moving into infinity, or perhaps a skyline that boggles the mind.  This does neither.  It sort of leaves me confused, but not necessarily in a bad way.  I stopped, looked and pondered this submission.  While I will feel anxious that it didn''t meet my idea of what a shot of Montana should be, it did make me rethink my paradigm.  Something that all art should do on some level.<br/> <br/>I think that I probably would have given this a 5 or a 6 under different circumstances, I''m bumping this up to an 8 simply because you befuddled me and made me take notice.  Thank you.</td>', 'Montana is such a wide open space.  I''ve been to the mountains and the plains of Big Sky country.  This is an intriguing shot because it goes against the preconceived ideas that the title infers.  I would expect to see a sweeping shot with plains moving into infinity, or perhaps a skyline that boggles the mind.  This does neither.  It sort of leaves me confused, but not necessarily in a bad way.  I stopped, looked and pondered this submission.  While I will feel anxious that it didn''t meet my idea of what a shot of Montana should be, it did make me rethink my paradigm.  Something that all art should do on some level. I think that I probably would have given this a 5 or a 6 under different circumstances, I''m bumping this up to an 8 simply because you befuddled me and made me take notice.  Thank you.', '2008-07-14 18:42:41.000000', NULL, 1),
(4824886, 695172, 76598, '<td valign="top">appears a bit over exposed to my eye</td>', 'appears a bit over exposed to my eye', '2008-07-14 18:47:12.000000', NULL, 1),
(4824890, 696305, 76598, '<td valign="top">the contrast between shade and sunrise is too great to make this a satisfying image.</td>', 'the contrast between shade and sunrise is too great to make this a satisfying image.', '2008-07-14 18:51:25.000000', NULL, 1),
(4824891, 696801, 76598, '<td valign="top">This image has a lot of potential, but you need to use all your pixels so we can appreciate it.  I feel sure your score will suffer because of that.</td>', 'This image has a lot of potential, but you need to use all your pixels so we can appreciate it.  I feel sure your score will suffer because of that.', '2008-07-14 18:52:52.000000', NULL, 1),
(4824892, 695602, 90658, '<td valign="top">Beautiful shot!  Most people NEVER see the green wheat.  It is only this color for such a short time.  I used to live in this area and I always thought that it was a beautiful area, but it is brown so much of the year.</td>', 'Beautiful shot!  Most people NEVER see the green wheat.  It is only this color for such a short time.  I used to live in this area and I always thought that it was a beautiful area, but it is brown so much of the year.', '2008-07-14 18:53:01.000000', NULL, 1),
(4824916, 695578, 90658, '<td valign="top">This is fabulous!</td>', 'This is fabulous!', '2008-07-14 19:00:53.000000', NULL, 1),
(4824958, 695769, 76598, '<td valign="top">I suspect you weren''t using a polarizing filter here.  It would have improved the photo greatly taking the glare off the rocks and bringing out the color in the plants.</td>', 'I suspect you weren''t using a polarizing filter here.  It would have improved the photo greatly taking the glare off the rocks and bringing out the color in the plants.', '2008-07-14 19:18:05.000000', NULL, 1),
(4824959, 696676, 76598, '<td valign="top">good image, but it doesn''t pop in any way, too little contrast, good positioning of the bell tower and roof in the image.</td>', 'good image, but it doesn''t pop in any way, too little contrast, good positioning of the bell tower and roof in the image.', '2008-07-14 19:18:54.000000', NULL, 1),
(4825000, 696239, 33672, '<td valign="top">A higher ISO might''ve made this outstanding view a bit sharper,</td>', 'A higher ISO might''ve made this outstanding view a bit sharper,', '2008-07-14 20:02:21.000000', NULL, 1),
(4825003, 696999, 33672, '<td valign="top">Spectacular view.</td>', 'Spectacular view.', '2008-07-14 20:02:46.000000', NULL, 1),
(4825004, 695397, 33672, '<td valign="top">Gritty with great tones and a comp that works really well.</td>', 'Gritty with great tones and a comp that works really well.', '2008-07-14 20:03:25.000000', NULL, 1),
(4825006, 696178, 33672, '<td valign="top">Nice comp. Could use a bit more contrast.</td>', 'Nice comp. Could use a bit more contrast.', '2008-07-14 20:03:53.000000', NULL, 1),
(4825008, 694990, 33672, '<td valign="top">Beautiful view, sky and comp. Could use a bit more contrast or a levels adjustment to really make this pop.</td>', 'Beautiful view, sky and comp. Could use a bit more contrast or a levels adjustment to really make this pop.', '2008-07-14 20:04:44.000000', NULL, 1),
(4825150, 696217, 76598, '<td valign="top">it appears over exposed</td>', 'it appears over exposed', '2008-07-14 21:53:39.000000', NULL, 1),
(4825237, 697097, 76598, '<td valign="top">The mist and the grass in front really adds, great job</td>', 'The mist and the grass in front really adds, great job', '2008-07-14 22:25:13.000000', NULL, 1),
(4825243, 696440, 90372, '<td valign="top">Have you ever seen the movie "Toys"? Ths shot look like it was taken right from the movie. Fabulous! 10:-)</td>', 'Have you ever seen the movie "Toys"? Ths shot look like it was taken right from the movie. Fabulous! 10:-)', '2008-07-14 22:28:31.000000', NULL, 1),
(4825282, 696873, 63244, '<td valign="top">Because the landscape (that is almost non-existant) isn''t the subject as much as the boats are, I don''t feel this fits the challenge.  It is still a beautiful photograph.</td>', 'Because the landscape (that is almost non-existant) isn''t the subject as much as the boats are, I don''t feel this fits the challenge.  It is still a beautiful photograph.', '2008-07-14 22:59:35.000000', NULL, 1),
(4825295, 696621, 63244, '<td valign="top">I like this, but your horizon is dead center.  Move the horizon up to enhance more of the water or move it down to play up the sky, city.</td>', 'I like this, but your horizon is dead center.  Move the horizon up to enhance more of the water or move it down to play up the sky, city.', '2008-07-14 23:13:40.000000', NULL, 1),
(4825310, 695830, 61222, '<td valign="top">Love this great tones and composition.</td>', 'Love this great tones and composition.', '2008-07-14 23:25:57.000000', NULL, 1),
(4825324, 695417, 90495, '<td valign="top">Fantastic shot! :D</td>', 'Fantastic shot! :D', '2008-07-14 23:37:38.000000', NULL, 1),
(4825325, 696671, 90495, '<td valign="top">I feel the stress leaving my body....</td>', 'I feel the stress leaving my body....', '2008-07-14 23:38:12.000000', NULL, 1),
(4825338, 696632, 67697, '<td valign="top">This is one of my favorites.  The silhouettes and perspective do such a nice job of making me feel like I''m there watching this scene.  Gorgeous sky too.</td>', 'This is one of my favorites.  The silhouettes and perspective do such a nice job of making me feel like I''m there watching this scene.  Gorgeous sky too.', '2008-07-14 23:51:46.000000', NULL, 1),
(4825339, 695188, 67697, '<td valign="top">I love the peaceful feeling this gives off. Gorgeous sunset and I love how the clouds are highlighted that way.  Beautiful shot.</td>', 'I love the peaceful feeling this gives off. Gorgeous sunset and I love how the clouds are highlighted that way.  Beautiful shot.', '2008-07-14 23:52:42.000000', NULL, 1),
(4825341, 696572, 67697, '<td valign="top">I love your capture of light.  The rocks and water look gorgeous.  Great timing with the birds too.</td>', 'I love your capture of light.  The rocks and water look gorgeous.  Great timing with the birds too.', '2008-07-14 23:53:18.000000', NULL, 1),
(4825344, 695524, 67697, '<td valign="top">I hope you put instructions on how you got the water to have the blue hue.  I''m guessing maybe this was a converted camera.  This is just gorgeous!</td>', 'I hope you put instructions on how you got the water to have the blue hue.  I''m guessing maybe this was a converted camera.  This is just gorgeous!', '2008-07-14 23:54:15.000000', NULL, 1),
(4825347, 697108, 67697, '<td valign="top">I love the light and shadows on the hills and mountains.  Beautiful capture in basic editing.</td>', 'I love the light and shadows on the hills and mountains.  Beautiful capture in basic editing.', '2008-07-14 23:55:15.000000', NULL, 1),
(4825349, 696871, 67697, '<td valign="top">Awesome shot.  I love how you caught all the separate bursts.  I hope you wrote down how you did that.  Love the clarity of the whole scene and the reflections in the water are beautiful too.</td>', 'Awesome shot.  I love how you caught all the separate bursts.  I hope you wrote down how you did that.  Love the clarity of the whole scene and the reflections in the water are beautiful too.', '2008-07-14 23:56:09.000000', NULL, 1),
(4825353, 696835, 67697, '<td valign="top">I love how the light highlights the textures of the mountain.  Beautiful blues and greens too.</td>', 'I love how the light highlights the textures of the mountain.  Beautiful blues and greens too.', '2008-07-14 23:57:47.000000', NULL, 1),
(4825356, 696914, 67697, '<td valign="top">Great way to make a playset look really fun.  I love the bursts of light although the more I look at it, the more I think barbed wire fence lol.  Anywho, very cool shot.</td>', 'Great way to make a playset look really fun.  I love the bursts of light although the more I look at it, the more I think barbed wire fence lol.  Anywho, very cool shot.', '2008-07-14 23:59:04.000000', NULL, 1),
