(4827140, 695416, 23098, '<td valign="top">Fireworks, city by the mountains and a wonderful moonlit night. Wonderful.</td>', 'Fireworks, city by the mountains and a wonderful moonlit night. Wonderful.', '2008-07-15 23:17:02.000000', NULL, 1),
(4827142, 697027, 23098, '<td valign="top">Colors, simplicity, composition and light. Nice work.</td>', 'Colors, simplicity, composition and light. Nice work.', '2008-07-15 23:18:11.000000', NULL, 1),
(4827143, 696832, 23098, '<td valign="top">Sharp, colors are good and I like the reflected clouds.</td>', 'Sharp, colors are good and I like the reflected clouds.', '2008-07-15 23:21:15.000000', NULL, 1),
(4827145, 696450, 23098, '<td valign="top">Green and beautiful, dramatic sky.</td>', 'Green and beautiful, dramatic sky.', '2008-07-15 23:22:07.000000', NULL, 1),
