(4827194, 695178, 81530, '<td valign="top">Yay Toronto!</td>', 'Yay Toronto!', '2008-07-15 23:46:19.000000', NULL, 1),
(4827199, 696373, 81530, '<td valign="top">I think I would have preferred to see rocks in the foreground instead of the plant, especially since there are so many of them.</td>', 'I think I would have preferred to see rocks in the foreground instead of the plant, especially since there are so many of them.', '2008-07-15 23:48:26.000000', NULL, 1),
(4827254, 696440, 67697, '<td valign="top">I love this one - especially with the cows.  The clouds filling up part of that background is gorgeous!  Beautiful green grass too.</td>', 'I love this one - especially with the cows.  The clouds filling up part of that background is gorgeous!  Beautiful green grass too.', '2008-07-16 00:22:08.000000', NULL, 1),
(4827255, 696439, 67697, '<td valign="top">Love the misty white water in the foreground.  Beautiful color in the reflections.</td>', 'Love the misty white water in the foreground.  Beautiful color in the reflections.', '2008-07-16 00:22:51.000000', NULL, 1),
(4827257, 696941, 67697, '<td valign="top">Lovely mirror reflection.  I like the boat as an added element of interest.</td>', 'Lovely mirror reflection.  I like the boat as an added element of interest.', '2008-07-16 00:23:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4827265, 695899, 67697, '<td valign="top">I like the simplicity of this.  I also like how the green tree breaks into the blue sky.</td>', 'I like the simplicity of this.  I also like how the green tree breaks into the blue sky.', '2008-07-16 00:25:17.000000', NULL, 1),
(4827270, 696428, 67697, '<td valign="top">Nice touch with having the couple there.  Must have been a wonderful moment to enjoy.  I like the ripples in the water too.</td>', 'Nice touch with having the couple there.  Must have been a wonderful moment to enjoy.  I like the ripples in the water too.', '2008-07-16 00:25:51.000000', NULL, 1),
(4827272, 696659, 67697, '<td valign="top">Beautiful sky.  I like looking at it thru the fence too.</td>', 'Beautiful sky.  I like looking at it thru the fence too.', '2008-07-16 00:26:34.000000', NULL, 1),
(4827276, 696616, 67697, '<td valign="top">I haven''t been to Spring Grove in a while.  Are you the same one that did Ault Park too?  I''m waiting for Eden Park now lol.  I love how the IR made this look like a cold winter day.  Beautiful processing.</td>', 'I haven''t been to Spring Grove in a while.  Are you the same one that did Ault Park too?  I''m waiting for Eden Park now lol.  I love how the IR made this look like a cold winter day.  Beautiful processing.', '2008-07-16 00:27:50.000000', NULL, 1),
(4827281, 696647, 67697, '<td valign="top">I like the yellow tones of the sky.  Gives this a different farmland feel.  Almost rustic.  Very nice.</td>', 'I like the yellow tones of the sky.  Gives this a different farmland feel.  Almost rustic.  Very nice.', '2008-07-16 00:28:34.000000', NULL, 1),
(4827285, 696049, 67697, '<td valign="top">Little too much yellow for my taste on the rocks.  But I love what the lighting is doing for the tree in the water.  It looks beautiful with the reflections and the simple sky.</td>', 'Little too much yellow for my taste on the rocks.  But I love what the lighting is doing for the tree in the water.  It looks beautiful with the reflections and the simple sky.', '2008-07-16 00:29:43.000000', NULL, 1),
(4827289, 696277, 67697, '<td valign="top">Gorgeous capture.  I love the spots of purple in the foreground.  It has to be amazing to see all those mountain peeks.  Very pretty.</td>', 'Gorgeous capture.  I love the spots of purple in the foreground.  It has to be amazing to see all those mountain peeks.  Very pretty.', '2008-07-16 00:31:05.000000', NULL, 1),
(4827292, 695172, 67697, '<td valign="top">I like how the scene is framed with the tree and the grass in front.  The boy in the tree is a nice surprise too.</td>', 'I like how the scene is framed with the tree and the grass in front.  The boy in the tree is a nice surprise too.', '2008-07-16 00:32:05.000000', NULL, 1),
(4827298, 694821, 67697, '<td valign="top">Cool catch.  Must be awesome to see in person.  Love the purples and blues too.</td>', 'Cool catch.  Must be awesome to see in person.  Love the purples and blues too.', '2008-07-16 00:33:03.000000', NULL, 1),
(4827301, 694906, 67697, '<td valign="top">Brrr I am glad it is summer here now.  Love how crisp and fresh the snow looks.</td>', 'Brrr I am glad it is summer here now.  Love how crisp and fresh the snow looks.', '2008-07-16 00:33:38.000000', NULL, 1),
(4827311, 696943, 67697, '<td valign="top">I like the perspective.  It needs a bit of something else because the background looks dull (or flat?).  Just wonddering how this looked in color...</td>', 'I like the perspective.  It needs a bit of something else because the background looks dull (or flat?).  Just wonddering how this looked in color...', '2008-07-16 00:35:18.000000', NULL, 1),
(4827315, 697100, 67697, '<td valign="top">I love how the flowers are framed in bokeh.  Very eye-catching.</td>', 'I love how the flowers are framed in bokeh.  Very eye-catching.', '2008-07-16 00:36:02.000000', NULL, 1),
(4827320, 696451, 67697, '<td valign="top">I really like the crisp reflections in the water.</td>', 'I really like the crisp reflections in the water.', '2008-07-16 00:36:55.000000', NULL, 1),
(4827326, 696503, 67697, '<td valign="top">I like everything but the distorted moon lol.  I love how the water has glowing streaks running thru it.</td>', 'I like everything but the distorted moon lol.  I love how the water has glowing streaks running thru it.', '2008-07-16 00:37:47.000000', NULL, 1),
(4827329, 696797, 67697, '<td valign="top">I like how your use of a silhouette takes this a step above a pond shot.  Beautiful glow on the water.</td>', 'I like how your use of a silhouette takes this a step above a pond shot.  Beautiful glow on the water.', '2008-07-16 00:38:43.000000', NULL, 1),
(4827337, 694551, 67697, '<td valign="top">The clouds over the moon is very cool - I think it''s my fave part.</td>', 'The clouds over the moon is very cool - I think it''s my fave part.', '2008-07-16 00:40:16.000000', NULL, 1),
(4827347, 697044, 67697, '<td valign="top">That''s fun how you included the trees in this.  Gives it that back to nature kind of feeling :)</td>', 'That''s fun how you included the trees in this.  Gives it that back to nature kind of feeling :)', '2008-07-16 00:42:29.000000', NULL, 1),
(4827363, 695436, 67697, '<td valign="top">I love the rays of sun.  The lighting beautifully enhances the textures of this scene.  Gorgeous!</td>', 'I love the rays of sun.  The lighting beautifully enhances the textures of this scene.  Gorgeous!', '2008-07-16 00:52:37.000000', NULL, 1),
(4827368, 697083, 49643, '<td valign="top">Beautiful location &amp; very well captured. The green is a little to saturated for my taste.</td>', 'Beautiful location & very well captured. The green is a little to saturated for my taste.', '2008-07-16 00:54:28.000000', NULL, 1),
(4827369, 696616, 49643, '<td valign="top">Beautifully captured &amp; well executed shot!</td>', 'Beautifully captured & well executed shot!', '2008-07-16 00:55:22.000000', NULL, 1),
(4827372, 696971, 49643, '<td valign="top">Interesting perspective &amp; nice contrasting colors.</td>', 'Interesting perspective & nice contrasting colors.', '2008-07-16 00:55:50.000000', NULL, 1),
(4827373, 696437, 49643, '<td valign="top">Beautiful composition,nice colors &amp; smooth feel of the image.</td>', 'Beautiful composition,nice colors & smooth feel of the image.', '2008-07-16 00:55:54.000000', NULL, 1),
(4827374, 697002, 49643, '<td valign="top">Beautiful location &amp; nicely composed image.</td>', 'Beautiful location & nicely composed image.', '2008-07-16 00:56:30.000000', NULL, 1),
(4827377, 696647, 49643, '<td valign="top">I like the colors. Some sky area looks washed out. I may have preferred a more wide angle shot of this beautiful location.</td>', 'I like the colors. Some sky area looks washed out. I may have preferred a more wide angle shot of this beautiful location.', '2008-07-16 00:57:33.000000', NULL, 1),
(4827381, 695524, 49643, '<td valign="top">Looks like a winner.Very well composed &amp; executed shot.</td>', 'Looks like a winner.Very well composed & executed shot.', '2008-07-16 00:58:08.000000', NULL, 1),
(4827382, 696278, 49643, '<td valign="top">Interesting clouds but image looks too post processed.</td>', 'Interesting clouds but image looks too post processed.', '2008-07-16 00:58:40.000000', NULL, 1),
