(4827411, 696049, 91527, '<td valign="top">Completely underrated.  I loved this shot, the colors and the reflections are amazing.</td>', 'Completely underrated.  I loved this shot, the colors and the reflections are amazing.', '2008-07-16 01:06:19.000000', NULL, 0),
(4827415, 695639, 67697, '<td valign="top">Excellent placement!  I''m glad this did well.  I love the perspective and the sky.  I also love how the buildings have variations in light.  Beautiful!</td>', 'Excellent placement!  I''m glad this did well.  I love the perspective and the sky.  I also love how the buildings have variations in light.  Beautiful!', '2008-07-16 01:07:39.000000', NULL, 0),
