INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4831272, 696572, 11078, '<td valign="top">stunning image added it to my favorites congrats</td>', 'stunning image added it to my favorites congrats', '2008-07-17 17:11:07.000000', NULL, 0),
(4831339, 696277, 60698, '<td valign="top">I just got back from Washington State and I wish I could have captured it''s beauty as you have here. This is beautiful and perfectly captures what is a truly breathtaking site. Love it!</td>', 'I just got back from Washington State and I wish I could have captured it''s beauty as you have here. This is beautiful and perfectly captures what is a truly breathtaking site. Love it!', '2008-07-17 17:41:38.000000', NULL, 0),
(4831347, 696990, 58691, '<td valign="top">There is a lot of unique activity at play in this image. First, the defined geometric shapes in the flagstone and in the telescope stand yield their corners to the soft-edged stones of the wall. Beyond that, moving vertically up the image, shapes become quite ambiguous and tightly blended together in the treetops. Continuing up the image, those shapes blend into an abyss and and then almost seem to erupt in larger form back out in the form of clouds. <br/> <br/>Additionally, there is a strong yellow floor to the image and a cool blue ceiling. Bring yellow and blue together and you get green - exactly what exists in the middle-thirds of the image. <br/> <br/>This is image is a visual journey in color, form and space.</td>', 'There is a lot of unique activity at play in this image. First, the defined geometric shapes in the flagstone and in the telescope stand yield their corners to the soft-edged stones of the wall. Beyond that, moving vertically up the image, shapes become quite ambiguous and tightly blended together in the treetops. Continuing up the image, those shapes blend into an abyss and and then almost seem to erupt in larger form back out in the form of clouds.  Additionally, there is a strong yellow floor to the image and a cool blue ceiling. Bring yellow and blue together and you get green - exactly what exists in the middle-thirds of the image.  This is image is a visual journey in color, form and space.', '2008-07-17 17:46:31.000000', NULL, 0),
(4831461, 696572, 14476, '<td valign="top">beautiful, just beautiful.  <br/> <br/>Hope your vacation was spectacular and you didn''t get too much of the smoke from the fires down that way.<br/></td>', 'beautiful, just beautiful.   Hope your vacation was spectacular and you didn''t get too much of the smoke from the fires down that way.', '2008-07-17 18:44:39.000000', NULL, 0),
